//! Cross-language contract: `OverlayScene` JSON emitted by the Python SDK
//! (`tantra_strategies.sdk.OverlaySceneEmitter`) and by the generic library
//! projection (`tantra_library.scene_projection.frame_to_scene`) deserializes
//! into the Rust `OverlayScene` and re-serializes to the identical wire JSON.
//!
//! Fixtures are generated by the Python kernel (tantra-strategies), not hand-written.

use serde_json::Value;
use tantra_ui_charts::scene::OverlayScene;

const ALL_LAYERS: &str = include_str!("fixtures/python_all_layers_scene.json");
const LIBRARY_PROJECTION: &str = include_str!("fixtures/python_library_projection_scene.json");

fn roundtrip(raw: &str) -> OverlayScene {
    let scene: OverlayScene = serde_json::from_str(raw).expect("python scene must deserialize");
    let original: Value = serde_json::from_str(raw).expect("fixture is JSON");
    let reencoded = serde_json::to_value(&scene).expect("scene serializes");
    assert_eq!(
        reencoded, original,
        "Rust re-serialization must match the Python wire JSON"
    );
    scene
}

#[test]
fn python_all_layer_scene_is_wire_identical() {
    let scene = roundtrip(ALL_LAYERS);
    assert_eq!(scene.signals.len(), 1);
    assert_eq!(scene.bands.len(), 1);
    assert_eq!(scene.stops.len(), 2);
    assert_eq!(scene.hedges.len(), 1);
    assert_eq!(scene.hints.len(), 1);
}

#[test]
fn python_library_projection_scene_is_wire_identical() {
    let scene = roundtrip(LIBRARY_PROJECTION);
    assert_eq!(scene.strategy_id, "ind.predictive-ranges");
    assert!(!scene.bands.is_empty());
    assert!(!scene.indicators.is_empty());
    assert!(!scene.signals.is_empty());
}
